message.content:
{
  "version": 2,
  "phase": "Phase1",
  "locale": "zh-Hant-written",
  "source": "deepseek Prompt D-modern",
  "chapters": [
    {
      "id": "Ch1",
      "title": "薄本與名片冊",
      "open": [
        "1988 年春，黃大仙屋邨走廊還有晨霧。",
        "阿偉口袋多了一本薄本、一疊名片冊。"
      ],
      "close": [
        "頭兩週過去，他學會看通告板，也學會等。",
        "還不算站穩，但已不只是旁觀。"
      ]
    },
    {
      "id": "Ch2",
      "title": "第一次試鏡",
      "open": [
        "第三週起，何生把試鏡日和即場的分別講得更細。",
        "阿偉開始自己跑通告板，記下每個地址和時間。"
      ],
      "close": [
        "第一單通告殺青，薄本多了一行收入。",
        "穩定有薪還遠，但這一步踏實了。"
      ]
    },
    {
      "id": "Ch3",
      "title": "人脈與對手",
      "open": [
        "通告越來越密，人事也越來越雜。",
        "誰給情報、誰給臉色，他開始分得清。"
      ],
      "close": [
        "人脈不是名片，是關鍵時刻的一句話。",
        "對手也一樣。"
      ]
    },
    {
      "id": "Ch4",
      "title": "春夏小結",
      "open": [
        "春夏之交，片場的燈還亮著。",
        "離穩定有薪還差一段，要結一次帳。"
      ],
      "close": [
        "評語定下，路還是要自己走。",
        "下一季再看成果。"
      ]
    }
  ],
  "beats": [
    {
      "id": "B01",
      "when": "W1",
      "speaker": "何生",
      "lines": [
        "薄本記數，名片冊記人。兩樣都別弄丟。",
        "我不會替你跑每一場。你自己去試。",
        "有不懂，先問，再記。"
      ]
    },
    {
      "id": "B02",
      "when": "W1-2",
      "speaker": "系統",
      "lines": [
        "通告板分兩欄：約試鏡日、即場候補。",
        "先看鎖區和日期，再記地點。",
        "約試鏡日要準時；即場看排隊。"
      ]
    },
    {
      "id": "B03",
      "when": "W2-3",
      "speaker": "阿偉",
      "lines": [
        "第一次報名訓練，手續比想像多。",
        "導師只看動作，不看解釋。",
        "結算時，薄本多了一行記錄。"
      ]
    },
    {
      "id": "B04",
      "when": "W3-4",
      "speaker": "系統",
      "lines": [
        "訓練滿兩次，社交課就會開放。",
        "社交課可以提升臨場應對。",
        "要不要報名，由你決定。"
      ]
    },
    {
      "id": "B05",
      "when": "W4-5",
      "speaker": "何生",
      "lines": [
        "第一次試鏡，成敗都算經驗。",
        "壓力會有。照本子做，別加戲。",
        "出來後告訴我，好壞都要說。"
      ]
    },
    {
      "id": "B06",
      "when": "W5-7",
      "speaker": "阿偉",
      "lines": [
        "多日拍攝，早出晚歸。",
        "殺青那刻，場務收聲，大家散開。",
        "薄本多了一筆收入，數目不大。"
      ]
    },
    {
      "id": "B07",
      "when": "W6-8",
      "speaker": "系統",
      "lines": [
        "林曉晴遞來一則通告情報，來源可靠。",
        "Vera 提醒形象要一致，別讓造型前後說話不一。",
        "張子駿寄語：先站穩，別急著成名。"
      ]
    },
    {
      "id": "B08",
      "when": "W8-9",
      "speaker": "阿偉",
      "lines": [
        "高俊傑當眾調侃我走位太慢，語氣帶笑。",
        "轉頭他先一步搶下那塊板。",
        "我記住位置，也記住這口氣。"
      ]
    },
    {
      "id": "B09",
      "when": "W9-10",
      "speaker": "系統",
      "lines": [
        "周采兒在場邊多看兩眼，好感慢慢夠了。",
        "她開口約一段小訪，問的只是片場日常。",
        "幾天後，小訪見報，名字首次印在版面上。"
      ]
    },
    {
      "id": "B10",
      "when": "W10-12",
      "speaker": "何生",
      "lines": [
        "（未達）穩定有薪還差一步，別鬆手，通告要接得更密。",
        "（已達）總算穩定有薪，站穩了再說下一步。"
      ]
    }
  ]
}
